<script lang="ts">let{data,form}=$props();const selected=$derived(data.effects.find((item)=>item.id===data.selectedEffectId));</script>
{#if form?.error}<p class="form-error">{form.error}</p>{/if}{#if form?.saved}<p class="form-success">Effect saved.</p>{/if}
<div class="rules-workspace admin-workspace-frame">
  <section class="panel stack rules-library"><div class="panel-head"><h2>Effect Library</h2><span>{data.effects.length}</span></div><form method="GET" class="inline"><input name="q" placeholder="Search Effects"/><button>Search</button></form><div class="admin-list">{#each data.effects as effect}<a class="admin-row admin-row-link" class:active={effect.id===data.selectedEffectId} href={`?effect=${effect.id}`}><div><strong>{effect.name}</strong><p class="muted">{effect.sourceType} · {effect.modifierCount} Modifiers</p></div></a>{/each}</div></section>
  <section class="panel stack rules-editor"><div class="panel-head"><h2>Effect Editor</h2>{#if selected}<span>{selected.referenceCount} references</span>{/if}</div><form method="POST" action="?/save" class="stack admin-form"><input type="hidden" name="effectId" value={selected?.id||''}/><label>Name<input name="name" value={selected?.name||''} required/></label><label>Type<select name="sourceType"><option value="condition" selected={selected?.sourceType==='condition'}>Condition</option><option value="combat_state" selected={selected?.sourceType==='combat_state'}>Combat State</option><option value="environment" selected={selected?.sourceType==='environment'}>Environment</option><option value="homebrew" selected={!selected||selected.sourceType==='homebrew'}>Homebrew</option></select></label><label>Description<textarea name="description">{selected?.description||''}</textarea></label><div class="mini-grid"><label>Duration<select name="durationType"><option value="variable">Variable</option><option value="timed" selected={selected?.durationType==='timed'}>Timed</option><option value="concentration" selected={selected?.durationType==='concentration'}>Concentration</option><option value="while_applicable" selected={selected?.durationType==='while_applicable'}>While Applicable</option></select></label><label>Rounds<input type="number" min="0" name="durationRounds" value={selected?.durationRounds??''}/></label></div><div class="mini-grid"><label>Stacking<select name="stackBehavior"><option value="refresh">Refresh</option><option value="stack" selected={selected?.stackBehavior==='stack'}>Stack</option><option value="reject" selected={selected?.stackBehavior==='reject'}>Reject</option></select></label><label>Expiry<select name="expiryBoundary"><option value="round_end">End of Round</option><option value="turn_start" selected={selected?.expiryBoundary==='turn_start'}>Start of Turn</option><option value="turn_end" selected={selected?.expiryBoundary==='turn_end'}>End of Turn</option><option value="manual" selected={selected?.expiryBoundary==='manual'}>Manual</option></select></label></div><label class="inline"><input type="checkbox" name="requiresConcentration" checked={selected?.requiresConcentration}/> Concentration</label><label class="inline"><input type="checkbox" name="isCondition" checked={selected?.isCondition}/> Condition</label><label class="inline"><input type="checkbox" name="isSelectable" checked={selected?.isSelectable??true}/> Players may activate manually</label><div class="button-row"><button>{selected?'Save Effect':'Create Effect'}</button>{#if selected}<button formaction="?/archive" class="danger">{selected.isArchived?'Restore':'Archive'}</button>{/if}</div></form></section>
  <section class="panel stack rules-create"><h2>Attached Modifiers</h2>{#if selected}<form method="POST" action="?/attach" class="stack admin-form"><input type="hidden" name="effectId" value={selected.id}/><label>Modifier<select name="modifierId">{#each data.modifiers.filter((item)=>!item.isArchived) as modifier}<option value={modifier.id}>{modifier.label||`${modifier.hookLabel} / ${modifier.operation}${modifier.baseValue?` / ${modifier.baseValue}`:''}`}</option>{/each}</select></label><label>Entry-specific Value<input name="valueOverride"/></label><label>Condition<input name="condition"/></label><label>Priority<input type="number" name="priority" value="0"/></label><button>Attach Modifier</button></form><div class="admin-list">{#each data.effectLinks as link}<article class="admin-row"><div><strong>{link.hookLabel} / {link.operation}</strong><p class="muted">{link.valueExpression||'No value'}{link.condition?` · ${link.condition}`:''}</p></div><form method="POST" action="?/detach"><input type="hidden" name="effectId" value={selected.id}/><input type="hidden" name="linkId" value={link.id}/><button class="danger compact-button">Remove</button></form></article>{:else}<p class="muted">No Modifiers attached.</p>{/each}</div>{/if}</section>
</div>
